/// What happened. Each kind is `<area>.<name>`; the owner of an area adds
/// its kinds here. Clients skip kinds they do not know through
/// [`EventProbe`], yet a client that decodes `EventKind` whole fails on a
/// kind it does not know, so a new kind is a major bump (spec 0030).
public enum EventKind: Codable, Sendable, Equatable {
	/// The subscriber missed events; take a new snapshot.
	case eventsGap(Gap)
	/// The daemon is shutting down.
	case daemonShuttingDown(ShuttingDown)
	/// An operation was created or changed state (spec 0007). The event's
	/// resource is the operation and its revision the operation's.
	case operationStateChanged(OperationSummary)
	/// An operation changed without changing state: stage, progress,
	/// `waitingOn`, the point of no return, or a cancel (spec 0007).
	case operationProgress(OperationSummary)
	/// A secret reference was stored, observed with another status,
	/// restored, or deleted (spec 0011). The event's resource is
	/// `{kind: secret, id: <reference>}`.
	case secretChanged(SecretChanged)
	/// An instance changed in a way that raised its revision: created,
	/// lifecycle, desired state, or an `Auto` port (spec 0010). The event's
	/// resource is the instance and its revision the instance's.
	case instanceStateChanged(InstanceStateChanged)
	/// The status of an instance changed (spec 0010). Clients apply it by
	/// `statusSeq`, never by revision. The event's resource is the
	/// instance.
	case instanceHealthChanged(InstanceHealthChanged)
	/// An instance row was deleted (spec 0010). The event's revision is
	/// the last revision plus one. Never sent before feature 20.
	case instanceRemoved(InstanceRemoved)
	/// The supervisor started or finished reconciling instances with the
	/// processes found after a daemon start (spec 0010). A daemon event:
	/// no resource, no revision.
	case daemonReconciling(DaemonReconciling)
	/// A runtime changed in a way that raised its revision: an install
	/// committed it, or a later feature changed it (spec 0018). The
	/// event's resource is the runtime and its revision the runtime's;
	/// there is no payload, so clients fetch it again with `runtime.get`.
	case runtimeStateChanged
	/// A restart plan was written or changed: its state, or the outcome of
	/// one of its instances (spec 0030). A daemon event: no resource, no
	/// revision.
	case daemonRestartPlan(RestartPlanView)
	/// The daemon settings or a default location changed (spec 0032). A
	/// daemon event: no resource, no revision; clients read `settings.get`
	/// again.
	case settingsChanged(SettingsChanged)
	/// The local entries of the catalog changed after a provider operation
	/// (spec 0037). A daemon event: no resource, no revision; clients read
	/// `catalog.list_providers` again.
	case catalogChanged(CatalogChanged)

	enum CodingKeys: String, CodingKey, Codable {
		case eventsGap = "events.gap",
			daemonShuttingDown = "daemon.shutting_down",
			operationStateChanged = "operation.state_changed",
			operationProgress = "operation.progress",
			secretChanged = "secret.changed",
			instanceStateChanged = "instance.state_changed",
			instanceHealthChanged = "instance.health_changed",
			instanceRemoved = "instance.removed",
			daemonReconciling = "daemon.reconciling",
			runtimeStateChanged = "runtime.state_changed",
			daemonRestartPlan = "daemon.restart_plan",
			settingsChanged = "settings.changed",
			catalogChanged = "catalog.changed"
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .eventsGap:
				if let content = try? container.decode(Gap.self, forKey: .content) {
					self = .eventsGap(content)
					return
				}
			case .daemonShuttingDown:
				if let content = try? container.decode(ShuttingDown.self, forKey: .content) {
					self = .daemonShuttingDown(content)
					return
				}
			case .operationStateChanged:
				if let content = try? container.decode(OperationSummary.self, forKey: .content) {
					self = .operationStateChanged(content)
					return
				}
			case .operationProgress:
				if let content = try? container.decode(OperationSummary.self, forKey: .content) {
					self = .operationProgress(content)
					return
				}
			case .secretChanged:
				if let content = try? container.decode(SecretChanged.self, forKey: .content) {
					self = .secretChanged(content)
					return
				}
			case .instanceStateChanged:
				if let content = try? container.decode(InstanceStateChanged.self, forKey: .content) {
					self = .instanceStateChanged(content)
					return
				}
			case .instanceHealthChanged:
				if let content = try? container.decode(InstanceHealthChanged.self, forKey: .content) {
					self = .instanceHealthChanged(content)
					return
				}
			case .instanceRemoved:
				if let content = try? container.decode(InstanceRemoved.self, forKey: .content) {
					self = .instanceRemoved(content)
					return
				}
			case .daemonReconciling:
				if let content = try? container.decode(DaemonReconciling.self, forKey: .content) {
					self = .daemonReconciling(content)
					return
				}
			case .runtimeStateChanged:
				self = .runtimeStateChanged
				return
			case .daemonRestartPlan:
				if let content = try? container.decode(RestartPlanView.self, forKey: .content) {
					self = .daemonRestartPlan(content)
					return
				}
			case .settingsChanged:
				if let content = try? container.decode(SettingsChanged.self, forKey: .content) {
					self = .settingsChanged(content)
					return
				}
			case .catalogChanged:
				if let content = try? container.decode(CatalogChanged.self, forKey: .content) {
					self = .catalogChanged(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(EventKind.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for EventKind"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .eventsGap(let content):
			try container.encode(CodingKeys.eventsGap, forKey: .type)
			try container.encode(content, forKey: .content)
		case .daemonShuttingDown(let content):
			try container.encode(CodingKeys.daemonShuttingDown, forKey: .type)
			try container.encode(content, forKey: .content)
		case .operationStateChanged(let content):
			try container.encode(CodingKeys.operationStateChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		case .operationProgress(let content):
			try container.encode(CodingKeys.operationProgress, forKey: .type)
			try container.encode(content, forKey: .content)
		case .secretChanged(let content):
			try container.encode(CodingKeys.secretChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		case .instanceStateChanged(let content):
			try container.encode(CodingKeys.instanceStateChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		case .instanceHealthChanged(let content):
			try container.encode(CodingKeys.instanceHealthChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		case .instanceRemoved(let content):
			try container.encode(CodingKeys.instanceRemoved, forKey: .type)
			try container.encode(content, forKey: .content)
		case .daemonReconciling(let content):
			try container.encode(CodingKeys.daemonReconciling, forKey: .type)
			try container.encode(content, forKey: .content)
		case .runtimeStateChanged:
			try container.encode(CodingKeys.runtimeStateChanged, forKey: .type)
		case .daemonRestartPlan(let content):
			try container.encode(CodingKeys.daemonRestartPlan, forKey: .type)
			try container.encode(content, forKey: .content)
		case .settingsChanged(let content):
			try container.encode(CodingKeys.settingsChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		case .catalogChanged(let content):
			try container.encode(CodingKeys.catalogChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

/// One event as a daemon frame carries it.
