	public init(subscriptionId: UInt32, sequence: UInt64, at: Date, resource: ResourceRef?, revision: UInt64?, kind: EventKind) {
		self.subscriptionId = subscriptionId
		self.sequence = sequence
		self.at = at
		self.resource = resource
		self.revision = revision
		self.kind = kind
	}
}

