/// The only frame a client sends.
public struct Request: Codable, Sendable, Equatable {
	/// 1 to 64 bytes of `[A-Za-z0-9._:-]`, chosen by the client and unique
	/// on the connection while the request runs. `stackly-ipc` uses a
	/// lowercase UUID v7.
	public let requestId: String
	/// 1 to 128 bytes of printable ASCII without spaces. Spec 0007 decides
	/// what it means.
	public let idempotencyKey: String?
	/// The method and its params.
	public let call: Call

	public init(requestId: String, idempotencyKey: String?, call: Call) {
		self.requestId = requestId
		self.idempotencyKey = idempotencyKey
		self.call = call
	}
}

/// One variant per method, with the same names and tags as [`Call`].
public enum Reply: Codable, Sendable, Equatable {
	/// The handshake was accepted.
	case daemonHandshake(HandshakeAccepted)
	/// Who the daemon is.
	case daemonGetInfo(DaemonInfo)
	/// The daemon's health.
	case daemonGetHealth(DaemonHealth)
	/// What the daemon supports.
	case daemonGetCapabilities(Capabilities)
	/// The daemon accepted the request and now runs the stop order.
	case daemonShutdown(ShutdownAccepted)
	/// The plan a restart would write and what would refuse it.
	case daemonRestartPreview(RestartPreview)
	/// The subscription started; its events follow.
	case eventsSubscribe(Subscribed)
	/// The subscription ended.
	case eventsUnsubscribe
	/// The operation with its steps and created items.
	case operationGet(OperationDetail)
	/// One page of operations.
	case operationList(OperationPage)
	/// The operation after the cancel, and what the cancel did.
	case operationCancel(CancelReply)
	/// The operation, queued again.
	case operationResume(OperationSummary)
	/// The closed operation and what was left over.
	case operationAbandon(AbandonReply)
	/// The engine's counters and limits.
	case operationGetStats(OperationStats)
	/// One page of audit rows.
	case auditList(AuditPage)
	/// Every catalog entry, in display order.
	case catalogListProviders(ListProvidersReply)
	/// One catalog entry in detail.
	case catalogGetProvider(ProviderDetail)
	/// The secret references and the store.
	case secretList(ListSecretsReply)
	/// The reference after the probe, and the store.
	case secretStatus(SecretStatusReply)
	/// The reference after the write, never the value.
	case secretSet(SetSecretReply)
	/// The value; the one reply that carries one.
	case secretReveal(RevealSecretReply)
	/// The reference that was deleted.
	case secretDelete(DeleteSecretReply)
	/// The operation that creates the instance.
	case instanceCreate(InstanceActionAccepted)
	/// The operation that starts the instance, or that it already runs.
	case instanceStart(InstanceActionAccepted)
	/// The operation that stops the instance, or that it already stopped.
	case instanceStop(InstanceActionAccepted)
	/// The operation that restarts the instance.
	case instanceRestart(InstanceActionAccepted)
	/// The operation that reloads the instance.
	case instanceReload(InstanceActionAccepted)
	/// The operation that force stops the instance, or that it already
	/// stopped.
	case instanceForceStop(InstanceActionAccepted)
	/// The instance.
	case instanceGet(InstanceSummary)
	/// One page of instances.
	case instanceList(InstancePage)
	/// The space left, read now.
	case storageGetCapacity(CapacityReport)
	/// The daemon settings.
	case settingsGet(DaemonSettingsView)
	/// The settings after the change, or as they were.
	case settingsUpdate(DaemonSettingsView)
	/// The storage locations.
	case storageListLocations(LocationList)
	/// The default location of the kind after the change.
	case storageSetLocation(StorageLocationView)
	/// The artifact the selector resolved to, and what happened to it.
	case runtimeInstall(InstallRuntimeReply)
	/// The artifact the selector resolved to.
	case runtimeResolve(ResolvedArtifact)
	/// One page of runtimes.
	case runtimeList(RuntimeListPage)
	/// The runtime.
	case runtimeGet(RuntimeDetail)
	/// The form for a new instance.
	case instanceGetCreateForm(CreateForm)
	/// The preflight rows, the field issues, and the equivalent command.
	case instancePreflight(CreatePreflight)
	/// The form and the draft of a duplicate.
	case instanceGetDuplicateForm(DuplicateForm)
	/// The detail of an instance.
	case instanceGetDetail(InstanceDetail)
	/// The size of a data folder, or null when none is cached.
	case instanceGetDataUsage(DataUsageReply)
	/// The samples after the cursor and the facts next to them.
	case instanceGetMetrics(MetricsReply)
	/// The config of the instance.
	case instanceConfigGet(InstanceConfigView)
	/// The verdict on a config change.
	case instanceConfigValidate(ConfigValidation)
	/// The operation that applies the change, or that nothing changed.
	case instanceConfigApply(ConfigApplyAccepted)
	/// The operation that keeps the active revision, or that nothing
	/// drifted.
	case instanceConfigKeepRevision(InstanceActionAccepted)
	/// The operation that renames the instance, or that the name is the
	/// same.
	case instanceRename(InstanceActionAccepted)
	/// The instance after its startup policy changed, or as it was.
	case instanceSetStartup(InstanceSummary)
	/// What Stop All would stop.
	case instancePreviewStopAll(StopAllPreview)
	/// How Stop All ended.
	case instanceStopAll(StopAllResult)
	/// The operation that changes the ports, or the verdict of a dry run.
	case instanceChangeEndpoints(ChangeEndpointsReply)
	/// One page of the log.
	case instanceLogsRead(LogPage)
	/// The follow started; its `log` frames follow.
	case instanceLogsFollow(LogsFollowing)
	/// The follow ended.
	case instanceLogsUnfollow
	/// The script is written.
	case instancePrepareTerminal(PrepareTerminalReply)
	/// The doctor report, one check per entry.
	case doctorRun(DoctorReport)
	/// What the staged bundle holds.
	case diagnosticsPreviewBundle(BundlePreview)
	/// The file the bundle was copied to.
	case diagnosticsExportBundle(ExportedBundle)
	/// What the validator found, even for a package that does not load.
	case providerValidate(ProviderValidation)
	/// What importing the folder would bring in.
	case providerPreviewImport(ImportPreview)
	/// The imported entry after the operation.
	case providerImport(ProviderDetail)
	/// The approved entry.
	case providerApprove(ProviderDetail)
	/// The entry after the revocation.
	case providerRevoke(ProviderDetail)
	/// The removed provider.
	case providerRemove(RemovedProvider)

