/// Reply of `instance.change_endpoints`: the operation that changes the
/// ports, or the verdict of a dry run. Tagged `type` and `content`.
public enum ChangeEndpointsReply: Codable, Sendable, Equatable {
	/// The change was accepted or equals the active revision.
	case applied(ConfigApplyAccepted)
	/// The verdict of `dryRun: true`; nothing was written.
	case dryRun(EndpointValidation)

	enum CodingKeys: String, CodingKey, Codable {
		case applied,
			dryRun
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .applied:
				if let content = try? container.decode(ConfigApplyAccepted.self, forKey: .content) {
					self = .applied(content)
					return
				}
			case .dryRun:
				if let content = try? container.decode(EndpointValidation.self, forKey: .content) {
					self = .dryRun(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(ChangeEndpointsReply.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ChangeEndpointsReply"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .applied(let content):
			try container.encode(CodingKeys.applied, forKey: .type)
			try container.encode(content, forKey: .content)
		case .dryRun(let content):
			try container.encode(CodingKeys.dryRun, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

/// The rule a folder broke, in the order the daemon checks them (spec 0032,
/// *Aturan lokasi*). Open.
public enum LocationRule: String, Codable, Sendable, Equatable {
	/// The path is relative.
	case notAbsolute = "not_absolute"
	/// The folder does not exist.
	case missing
	/// The path is not a folder.
	case notDirectory = "not_directory"
	/// The path, or a folder above it, is a symlink.
	case symlink
	/// Another user owns the folder.
	case notOwned = "not_owned"
	/// Group or other can write to the folder.
	case tooOpen = "too_open"
	/// The folder is one macOS may block the daemon from.
	case protectedFolder = "protected_folder"
	/// The disk is not local.
	case notLocalVolume = "not_local_volume"
	/// The disk is not inside this Mac.
	case notInternalVolume = "not_internal_volume"
	/// The folder overlaps another Stackly location or root.
	case overlapsRoot = "overlaps_root"
	/// A `Stackly` folder is there and is not one of this registry.
	case foreignMarker = "foreign_marker"
	/// The daemon cannot create the folders it needs.
	case notWritable = "not_writable"
	/// A rule this build does not know. The daemon never sends it.
	case unrecognized
}

/// Every frame the daemon sends. Adding a variant a client may receive
/// without asking is a new major; `log` is sent only on a connection that
/// called `instance.logs_follow`, so it came as a minor (spec 0027).
public enum ServerFrame: Codable, Sendable, Equatable {
	/// The reply to one request.
	case response(Response)
	/// The error for one request, or for a frame without a readable
	/// request.
	case error(ErrorFrame)
	/// One event for one subscription.
	case event(Event)
	/// Log entries of one follow (spec 0027).
	case log(LogFrame)

	enum CodingKeys: String, CodingKey, Codable {
		case response,
			error,
			event,
			log
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .response:
				if let content = try? container.decode(Response.self, forKey: .content) {
					self = .response(content)
					return
				}
			case .error:
				if let content = try? container.decode(ErrorFrame.self, forKey: .content) {
					self = .error(content)
					return
				}
			case .event:
				if let content = try? container.decode(Event.self, forKey: .content) {
					self = .event(content)
					return
				}
			case .log:
				if let content = try? container.decode(LogFrame.self, forKey: .content) {
					self = .log(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(ServerFrame.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ServerFrame"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .response(let content):
			try container.encode(CodingKeys.response, forKey: .type)
			try container.encode(content, forKey: .content)
		case .error(let content):
			try container.encode(CodingKeys.error, forKey: .type)
			try container.encode(content, forKey: .content)
		case .event(let content):
			try container.encode(CodingKeys.event, forKey: .type)
			try container.encode(content, forKey: .content)
		case .log(let content):
			try container.encode(CodingKeys.log, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}
